// Single-file bundle of supabase/functions/admin-users (generated by npm run bundle:functions). Paste into the dashboard editor.

import { createClient } from "npm:@supabase/supabase-js@2";

// supabase/functions/admin-users/index.ts
const cors = {
	"Access-Control-Allow-Origin": "*",
	"Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
	"Access-Control-Allow-Methods": "POST, OPTIONS"
};
const json = (body, status = 200) => new Response(JSON.stringify(body), {
	status,
	headers: {
		...cors,
		"Content-Type": "application/json"
	}
});
const ASSIGNABLE = [
	"super_admin",
	"administrator",
	"accountant",
	"billing_officer",
	"collection_agent",
	"technician",
	"support_officer"
];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
Deno.serve(async (req) => {
	if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
	if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);
	const url = Deno.env.get("SUPABASE_URL");
	const anon = Deno.env.get("SUPABASE_ANON_KEY");
	const service = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
	const authHeader = req.headers.get("Authorization") ?? "";
	if (!authHeader) return json({ error: "unauthorized" }, 401);
	const { data: access, error: accessErr } = await createClient(url, anon, {
		global: { headers: { Authorization: authHeader } },
		auth: { persistSession: false }
	}).rpc("my_access");
	if (accessErr || !access) return json({ error: "unauthorized" }, 401);
	const perms = access.permissions;
	if (!access.is_active) return json({ error: "forbidden" }, 403);
	const required = (a) => a === "create_customer_login" ? "customers.update" : "staff.manage";
	const callerIsSuper = access.roles.includes("super_admin");
	const callerId = access.user_id;
	const admin = createClient(url, service, { auth: { persistSession: false } });
	let body;
	try {
		body = await req.json();
	} catch {
		return json({ error: "invalid_json" }, 400);
	}
	const action = String(body.action ?? "");
	if (!perms.includes(required(action))) return json({ error: "forbidden" }, 403);
	const roleId = async (code) => (await admin.from("roles").select("id").eq("code", code).single()).data?.id;
	const targetIsSuper = async (userId) => {
		const { data } = await admin.from("user_roles").select("roles!inner(code)").eq("user_id", userId).eq("roles.code", "super_admin");
		return (data?.length ?? 0) > 0;
	};
	const audit = (act, record, metadata = {}) => admin.from("audit_logs").insert({
		actor_id: callerId,
		category: "data",
		action: act,
		table_name: "profiles",
		record_id: record,
		metadata
	});
	if (action === "create") {
		const email = String(body.email ?? "").trim().toLowerCase();
		const password = String(body.password ?? "");
		const fullName = String(body.full_name ?? "").trim();
		const phone = body.phone ? String(body.phone).trim() : null;
		const role = String(body.role ?? "");
		const language = body.language === "en" ? "en" : "bn";
		if (!EMAIL.test(email)) return json({ error: "invalid_email" }, 400);
		if (password.length < 8) return json({ error: "password_too_short" }, 400);
		if (!fullName) return json({ error: "name_required" }, 400);
		if (!ASSIGNABLE.includes(role)) return json({ error: "invalid_role" }, 400);
		if (role === "super_admin" && !callerIsSuper) return json({ error: "only_super_admin_can_grant_super_admin" }, 403);
		const rid = await roleId(role);
		if (!rid) return json({ error: "role_not_found" }, 400);
		const { data, error } = await admin.auth.admin.createUser({
			email,
			password,
			email_confirm: true,
			user_metadata: { full_name: fullName }
		});
		if (error || !data.user) return json({ error: error?.message ?? "create_failed" }, 400);
		const uid = data.user.id;
		const upd = await admin.from("profiles").update({
			full_name: fullName,
			phone,
			language
		}).eq("id", uid);
		const ins = await admin.from("user_roles").insert({
			user_id: uid,
			role_id: rid,
			assigned_by: callerId
		});
		if (upd.error || ins.error) {
			await admin.auth.admin.deleteUser(uid);
			return json({ error: (upd.error ?? ins.error).message }, 400);
		}
		await audit("user_created", uid, {
			role,
			email
		});
		return json({ user_id: uid });
	}
	if (action === "set_password") {
		const userId = String(body.user_id ?? "");
		const password = String(body.password ?? "");
		if (password.length < 8) return json({ error: "password_too_short" }, 400);
		if (!userId) return json({ error: "user_required" }, 400);
		if (await targetIsSuper(userId) && !callerIsSuper) return json({ error: "only_super_admin_can_change_super_admin" }, 403);
		const { error } = await admin.auth.admin.updateUserById(userId, { password });
		if (error) return json({ error: error.message }, 400);
		await audit("user_password_reset", userId);
		return json({ ok: true });
	}
	if (action === "set_role") {
		const userId = String(body.user_id ?? "");
		const role = String(body.role ?? "");
		if (!ASSIGNABLE.includes(role)) return json({ error: "invalid_role" }, 400);
		if (userId === callerId) return json({ error: "cannot_change_own_role" }, 400);
		if ((role === "super_admin" || await targetIsSuper(userId)) && !callerIsSuper) return json({ error: "only_super_admin_can_change_super_admin" }, 403);
		const rid = await roleId(role);
		if (!rid) return json({ error: "role_not_found" }, 400);
		const del = await admin.from("user_roles").delete().eq("user_id", userId);
		const ins = await admin.from("user_roles").insert({
			user_id: userId,
			role_id: rid,
			assigned_by: callerId
		});
		if (del.error || ins.error) return json({ error: (del.error ?? ins.error).message }, 400);
		await audit("user_role_changed", userId, { role });
		return json({ ok: true });
	}
	if (action === "create_customer_login") {
		const customerId = String(body.customer_id ?? "");
		const password = String(body.password ?? "");
		if (password.length < 8) return json({ error: "password_too_short" }, 400);
		const { data: c } = await admin.from("customers").select("id, phone, full_name, user_id, customer_code, archived_at").eq("id", customerId).single();
		if (!c || c.archived_at) return json({ error: "customer_not_found" }, 404);
		if (c.user_id) return json({ error: "customer_already_has_login" }, 400);
		const digits = String(c.phone).replace(/\D/g, "");
		const e164 = digits.startsWith("880") ? `+${digits}` : digits.startsWith("0") ? `+88${digits}` : `+880${digits}`;
		const { data, error } = await admin.auth.admin.createUser({
			phone: e164,
			password,
			phone_confirm: true,
			user_metadata: { full_name: c.full_name }
		});
		if (error || !data.user) return json({ error: error?.message ?? "create_failed" }, 400);
		const uid = data.user.id;
		const rid = await roleId("customer");
		const link = await admin.from("customers").update({ user_id: uid }).eq("id", c.id);
		const role = rid ? await admin.from("user_roles").insert({
			user_id: uid,
			role_id: rid,
			assigned_by: callerId
		}) : { error: { message: "customer role missing" } };
		if (link.error || role.error) {
			await admin.auth.admin.deleteUser(uid);
			return json({ error: (link.error ?? role.error).message }, 400);
		}
		await audit("customer_login_created", c.id, { customer_code: c.customer_code });
		return json({
			ok: true,
			customer_code: c.customer_code
		});
	}
	return json({ error: "unknown_action" }, 400);
});
